# hypothesis: type(x) == C and type(x) != C guards on an Any parameter narrow differently when the guard sits in a nested scope, and a metaclass whose __eq__ always returns True makes the equality guard take the wrong branch at runtime.
from typing import Any, assert_type, reveal_type


class EqualMeta(type):
    def __eq__(cls, other: object) -> bool:
        return True

    def __hash__(cls) -> int:
        return 0


class Equal(metaclass=EqualMeta):
    pass


class Holder:
    def check(self, value: Any, sample: int | str) -> str:
        def inner() -> str:
            if type(value) == type(sample):
                reveal_type(value)
                return 'same'
            return 'different'

        return inner()


def metaclass_guard(value: Equal | str, sample: str) -> str:
    if type(value) == type(sample):
        reveal_type(value)
        return 'eq'
    if type(value) != type(sample):
        reveal_type(value)
    return 'other'


def any_guard(value: Any) -> str:
    if type(value) != int:
        assert_type(value, Any)
        return 'not int'
    assert_type(value, Any)
    return 'int'


h = Holder()
print(h.check(3, 4), h.check(3, 'b'))
print(metaclass_guard(Equal(), 'x'), metaclass_guard('x', 'y'))
print(any_guard(3), any_guard('s'))
